sql:
# 使用 Sherlock 工具探测用户名 "ce" 在各平台的注册情况
result = mcp_sherlock_lookup_username(username="ce", include_available=False, include_nsfw=False)

# 整理结果：只保留已注册（有账号）的平台
registered = []
if isinstance(result, dict):
    # Sherlock 返回的通常是包含各站点结果的字典
    for site, info in result.items():
        if isinstance(info, dict):
            status = info.get("status", "")
            if status.upper() in ("CLAIMED", "FOUND", "EXISTS"):
                registered.append({
                    "platform": site,
                    "url": info.get("url_user", info.get("url", "")),
                    "status": status
                })
        elif isinstance(info, str) and info.upper() in ("CLAIMED", "FOUND", "EXISTS"):
            registered.append({"platform": site, "status": info})
elif isinstance(result, list):
    for item in result:
        if isinstance(item, dict):
            status = item.get("status", "")
            if status.upper() in ("CLAIMED", "FOUND", "EXISTS"):
                registered.append({
                    "platform": item.get("site", item.get("name", "")),
                    "url": item.get("url_user", item.get("url", "")),
                    "status": status
                })

RESULT = {
    "username": "ce",
    "registered_platforms": registered,
    "total_found": len(registered),
    "raw_result_preview": str(result)[:2000]  # 保留原始结果以便调试
}

